```rust
/// [`spending`], for a unit whose share of the line the hex has settled - the shape `forecast_hex`
/// always produces for a `For Sale` line, and the one `no_market`'s `market_share` cannot express.
fn spending_with_share(
    held: i64,
    intents: &[PlacedIntent],
    purchase: &dyn Fn(&str) -> PurchaseAnswer,
    share: i64,
) -> UnitSilver {
    let receipts = Receipts::default();
    let market_share =
        move |_item: &str, side: MarketSide| matches!(side, MarketSide::Buying).then_some(share);
    forecast_unit(
        UnitFacts { held, ..facts(1, intents, &receipts) },
        RegionWages::default(),
        PoolShares::default(),
        FactionPurse::default(),
        0,
        Lookups { purchase, market_share: &market_share, ..no_market() },
        None,
    )
}
```

