#[cfg_attr(
    test,
    derive(ts_rs::TS),
    ts(export, export_to = "../../../ruleset/src/generated/ControlCap.ts")
)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ControlCap {
    pub multiplier: i64,
    pub offset: i64,
    pub exponent: u32,
