```ts
/**
 * The item list as the column shows it. `created` is what a CAST brings that the game leaves
 * partly to chance: the amounts in `items` are already the most the unit may end with, so each
 * entry's low end is that figure less the part that rests on a chance.
 */
export function formatItems(
  items: readonly ItemAmount[],
  created: readonly CreatedItem[] = [],
): string {
  const shortfall = new Map<string, number>();
  for (const item of created) {
    shortfall.set(item.tag, (shortfall.get(item.tag) ?? 0) + (item.most - item.fewest));
  }
  return items
    .map((item) => {
      const gap = shortfall.get(item.tag) ?? 0;
      return gap > 0
        ? `${item.amount - gap}-${item.amount} ${item.tag}`
        : `${item.amount} ${item.tag}`;
    })
    .join(", ");
}
```

