/** The rows the bulk actions act on: the pick when it is two or more, the cursor row otherwise. */
const acting = useMemo(
  () => (pick.ids.size >= 2 ? pickedIn(pick, visible) : selectedUnit ? [selectedUnit] : []),
  [pick, visible, selectedUnit]
